/**
 * =============================================================================
 * SCOPE ENFORCEMENT MIDDLEWARE
 * =============================================================================
 * Validates that the authenticated user/app has the required scopes.
 * Scopes come from: OAuth app's allowed_scopes, API key scopes, or JWT claims.
 * Regular users (JWT login) get wildcard '*' — full access to their own data.
 * =============================================================================
 */

import { Request, Response, NextFunction } from 'express';
import { hasScope } from '@secuura/shared/security/scopes';
import { logger } from '../utils/logger';

/**
 * Require one or more scopes to access an endpoint.
 * If the user has ANY of the listed scopes (or '*'), access is granted.
 *
 * Usage:
 *   router.get('/api/documents', requireScope('documents:read'), handler);
 *   router.post('/api/certifications/issue', requireScope('certifications:write'), handler);
 */
export function requireScope(...requiredScopes: string[]) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const user = (req as any).user;

    // No user = not authenticated (should be caught by auth middleware first)
    if (!user) {
      res.status(401).json({ success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } });
      return;
    }

    // Regular users (JWT login, not OAuth/API key) get full access to their own data
    // They don't have explicit scopes — their access is controlled by RBAC, not scopes
    const authMethod = user.authMethod || 'jwt';
    if (authMethod === 'jwt' || authMethod === 'email') {
      next();
      return;
    }

    // OAuth apps and API keys have explicit scopes
    const userScopes: string[] = user.scopes || [];

    // Wildcard = all scopes
    if (userScopes.includes('*')) {
      next();
      return;
    }

    // Check if user has at least one of the required scopes
    const hasScope = requiredScopes.some(s => userScopes.includes(s));
    if (hasScope) {
      next();
      return;
    }

    res.status(403).json({
      error: 'Insufficient scope',
      required: requiredScopes,
      granted: userScopes,
      hint: `This endpoint requires one of: ${requiredScopes.join(', ')}. Your app has: ${userScopes.join(', ') || 'none'}.`,
    });
  };
}

/**
 * Attach scopes to the request from OAuth token claims.
 * Called after authentication middleware has set req.user.
 *
 * KS-835: what this reads, stated honestly. An OAuth-minted token carries the
 * granted scopes as the `scopes` ARRAY claim (services/auth jwt.ts) and
 * authenticateToken puts the verified claims on req.user as-is — so for every
 * token the auth service mints today, `user.scopes` is already present and
 * this middleware leaves it alone. The singular space-separated `scope` string
 * below is the RFC 6749 §3.3 wire form; nothing in this platform mints it, so
 * the parse is a compatibility arm for a token some other issuer might shape
 * that way, and it only ever runs when no `scopes` array is present — it never
 * widens an existing grant. The ticket's finding was that this branch READ AS a
 * control while the mint carried no grant at all; the grant is carried now, and
 * `requireScope` gates the 'oauth' label on it.
 */
export function attachScopes(req: Request, _res: Response, next: NextFunction): void {
  const user = (req as any).user;
  if (user && !user.scopes) {
    // Parse scope string from JWT claims (space-separated)
    const scopeStr = user.scope || '';
    if (scopeStr) {
      user.scopes = scopeStr.split(/[\s,]+/).filter((s: string) => s.length > 0);
    }
  }
  next();
}


/**
 * =============================================================================
 * KS-843 — SCOPE-OR-ROLE, WITH A LOGGED GRACE AND A SWITCH
 * =============================================================================
 * Kam ruled 2026-09-03: *"Dedicated scope `subjects:erase` — mint it for S's
 * key at registration; refuse others 403."*
 *
 * The refusal cannot simply be switched on. Every connector key issued before
 * the scope existed lacks it, and **Platform K has no way to add a scope to an
 * existing key** — the security service's key surface is create / list /
 * revoke / validate, with no PATCH and no `UPDATE svc_api_keys` anywhere. The
 * only route to a scoped key is rotation, which is platform-admin-only. So a
 * bare `requireScope` would 403 a live partner integration with no forward fix.
 *
 * This middleware is therefore the cutover instrument, not the end state:
 *
 *   switch OFF (default) — a caller holding the scope passes. A caller that
 *                          lacks it but holds an accepted ROLE also passes,
 *                          and ONE structured line is logged naming the key,
 *                          the org and the route. That log is the evidence
 *                          that tells an operator when it is safe to flip.
 *   switch ON            — only the scope passes; role-only callers get 403.
 *
 * The switch is read PER REQUEST, not at module load, so it can be flipped by
 * restarting with a different environment rather than rebuilding, and so a
 * test can drive both branches in one process.
 *
 * TWO DELIBERATE DIFFERENCES FROM `requireScope` ABOVE, both load-bearing:
 *
 * 1. **No `authMethod` short-circuit.** `requireScope` returns `next()` for
 *    any principal whose `authMethod` is `jwt` or `email`. KS-835 records that
 *    OAuth-minted tokens carry the `email` label too, so that branch is an
 *    open door, not a convenience. A new auth door must not inherit it — this
 *    one grants on the scope or the role, and on nothing else.
 * 2. **Wildcards are honoured via `hasScope`**, so `*` and `subjects:*` work
 *    the way the shared vocabulary says they do. `requireScope`'s
 *    `userScopes.includes(s)` is an exact-match test that silently ignores
 *    both.
 *
 * @param requiredScope the scope that grants access outright
 * @param allowedRoles  roles accepted DURING THE GRACE only
 * @param enforceFlag   env var name; `'true'` means scope-only
 * =============================================================================
 */
export function requireScopeOrRole(
  requiredScope: string,
  allowedRoles: readonly string[],
  enforceFlag: string,
) {
  return (req: Request, res: Response, next: NextFunction): void => {
    const user = (req as { user?: Record<string, unknown> }).user;

    if (!user) {
      res.status(401).json({ success: false, error: { code: 'UNAUTHORIZED', message: 'Authentication required' } });
      return;
    }

    const scopes = (user.scopes as string[] | undefined) ?? [];
    if (hasScope(scopes, requiredScope)) {
      next();
      return;
    }

    const role = typeof user.role === 'string' ? user.role : '';
    const roleAccepted = allowedRoles.includes(role);
    // Read per request: the switch is an operational control, not a build-time
    // constant. `!== 'true'` rather than `=== 'false'` so anything unset,
    // misspelled or empty leaves the grace ON — a typo must not silently start
    // refusing a partner.
    const enforcing = process.env[enforceFlag] === 'true';

    if (roleAccepted && !enforcing) {
      // The whole point of the grace. One line per admitted-without-scope
      // request, carrying what an operator needs to chase the key down.
      logger.warn('[KS-843] erasure allowed by ROLE without the required scope — grace is ON', {
        requiredScope,
        role,
        connectorId: user.connectorId ?? null,
        organizationId: user.organizationId ?? null,
        tenantId: user.tenantId ?? null,
        method: req.method,
        route: req.originalUrl,
        enforceFlag,
        grantedScopes: scopes,
      });
      next();
      return;
    }

    res.status(403).json({
      success: false,
      error: {
        code: 'INSUFFICIENT_SCOPE',
        message: `This endpoint requires the '${requiredScope}' scope.`,
        required: requiredScope,
        granted: scopes,
      },
    });
  };
}
